import{j as e}from"./blog-pages-CSFOXFVG.js";import{V as t}from"./_VerticalTemplate-Cb1v2bDx.js";import"./accordion-BkLbp7nb.js";import"./index-CTB1cNbD.js";import"./dt-3d-models-BDzdpr8y.js";import"./index-DUpvVbK-.js";const r={slug:"nuclear",industryDisplay:"Nuclear",industryShort:"nuclear utilities, fuel-cycle operators and EPCs",heroSubhead:"ASME Section III and Section XI aligned in-house qualification programs for new-build, in-service inspection (ISI), and decommissioning crews. Built to satisfy 10 CFR 50 Appendix B, ASME NQA-1, and the ANSI/ASNT CP-189 employer certification track that nuclear utilities default to.",primaryStandards:["ASME Section III","ASME Section XI","ANSI/ASNT CP-189","10 CFR 50 Appendix B","ASME NQA-1","ASME Section V"],methods:[{method:"Ultrasonic Testing — Conventional + PAUT + TOFD (PDI Appendix VIII)",levels:"Level I → III",roleFit:"ISI Level II/III, reactor-vessel exam teams",codeRef:"ASME XI Mandatory Appendix VIII (PDI), ASME V Article 4"},{method:"Radiographic Testing — film + CR for safety-class welds",levels:"Level I → III",roleFit:"New-build construction RT crews, decom characterisation teams",codeRef:"ASME III NB-5000 / NC-5000, ASME V Article 2, 10 CFR 34"},{method:"Eddy Current Testing — steam-generator + heat-exchanger tubing",levels:"Level II + III",roleFit:"Steam-generator outage crews, condenser inspection leads",codeRef:"ASME XI Mandatory Appendix IV, EPRI guidelines"},{method:"Magnetic Particle Testing — wet fluorescent / dry visible",levels:"Level I → II",roleFit:"Containment liner welds, support-structure inspection",codeRef:"ASME III NB-5340, ASME V Article 7"},{method:"Liquid Penetrant Testing — Type II Method C (post-emulsifiable)",levels:"Level I → II",roleFit:"Cladding QC, surface defect screening on austenitic",codeRef:"ASME III NB-5350, ASME V Article 6"},{method:"Visual Testing — VT-1 / VT-2 / VT-3 per ASME XI",levels:"Level II",roleFit:"Containment leak-rate testing teams, IWE/IWL inspectors",codeRef:"ASME XI IWA-2210, IWE, IWL"},{method:"PDI (Performance Demonstration Initiative) qualification prep",levels:"Specialist",roleFit:"ISI UT operators on dissimilar-metal welds, RPV nozzles",codeRef:"ASME XI Mandatory Appendix VIII via EPRI PDI"}],skillGaps:[{gap:"ISI UT operators who hold Level II SNT-TC-1A but have not closed PDI Appendix VIII practical demonstration",impact:"Cannot be deployed on dissimilar-metal welds or RPV nozzles; outage crew gap that must be plugged with high-cost contractors."},{gap:"Steam-generator eddy current inspectors weak on absolute / differential coil interpretation around tube-sheet support intersections",impact:"Missed indications, EPRI peer-review findings, regulatory letter risk."},{gap:"Engineers certified outside the CP-189 framework being mobilised to a US nuclear site without the recurrent-training and QA-program documentation",impact:"Site-access denial during outage; day-rate technicians billed without producing inspections."},{gap:"VT-1 / VT-2 / VT-3 inspectors weak on the distinction between visual examination categories under ASME XI IWA-2210",impact:"Inspection rejected during ASME XI implementation review; outage critical path slips."}],tracks:[{role:"ISI UT Operator",progression:"Level II UT → PAUT Level II → PDI Appendix VIII demonstration → Level III pathway",coreMethods:"UT, PAUT, TOFD",hoursTotal:"240–320 instructor-led + PDI demonstration weeks"},{role:"ISI Eddy Current Operator",progression:"Level II ET → bobbin + array specialisations → Level III",coreMethods:"ET, RFT",hoursTotal:"200–240 instructor-led + EPRI workshop"},{role:"ASME XI Visual Inspector (VT-1/2/3)",progression:"Visual Level II + ASME XI VT-1/2/3 specific training",coreMethods:"VT-1, VT-2, VT-3",hoursTotal:"80–120 instructor-led + outage shadowing"},{role:"New-Build Construction Inspector",progression:"Level II UT, RT, MT, PT mapped to ASME III NB / NC / ND",coreMethods:"UT, RT, MT, PT",hoursTotal:"240–320 instructor-led + 1,200 OJT"},{role:"Decommissioning Characterisation Inspector",progression:"Level II UT + RT + radiation safety bridging",coreMethods:"UT, RT, characterisation methods",hoursTotal:"180–240 instructor-led"}],pricing:[{headcount:"10–24 engineers",perHead:"Quote on request",notes:"Nuclear premium reflects CP-189 documentation overhead, PDI prep, and ASME XI specificity."},{headcount:"25–49 engineers",perHead:"Quote on request",notes:"Multi-method outage-readiness cohorts; includes EPRI guideline mapping."},{headcount:"50–99 engineers",perHead:"Quote on request",notes:"Dedicated Level III on-site for the duration; PDI demonstration coordination."},{headcount:"100+ engineers",perHead:"Quote on request",notes:"Utility-wide multi-station programme, NQA-1 compliant training records, regulator-ready evidence pack."}],deliveryNote:"Nuclear cohorts run almost exclusively on-site or at qualified training facilities — radiation-controlled work, PDI demonstration coupons, and the QA program require a controlled environment that cannot be replicated through pure LMS delivery. LMS handles theory and recurrent CP-189 written-practice refreshers. Hybrid is standard, with on-site practicals scheduled around outage windows so engineers are current when the unit comes down.",complianceFootnote:"Nuclear training records are a 10 CFR 50 Appendix B QA record. Retention is utility-wide and effectively permanent. Our deliverable is mapped to ASME NQA-1 Subpart 2.7 — instructor qualifications, lesson plans, exam keys, grade sheets, vision records, and OJT logs are all signed off and version-controlled so they survive an NRC, CNSC, ONR, or IAEA review without findings.",caseStudy:{headline:"Major nuclear utility — multi-station outage programme — 78-engineer multi-year cohort",body:"A North American nuclear utility with multiple PWR units needed to refresh its in-house ISI workforce ahead of a five-year outage cycle. Atlantis NDT delivered a multi-cohort programme covering UT Level II/III refresher with PDI Appendix VIII practical preparation, eddy current Level II for steam-generator outages, and ASME XI VT-1/2/3 for containment work. Across three years and 78 engineers, the programme delivered first-attempt Level III pass rates of 81% and zero NRC personnel-qualification findings during the inspection-period reviews that ran in parallel. Per-head training cost landed 28% below the previous arrangement of sending engineers to an open-enrolment third-party school in batches of two and three."},cityLinks:[{slug:"toronto",label:"Toronto"},{slug:"houston",label:"Houston"}],wordCountHint:"Nuclear NDT corporate training operates under a documentation regime that has no equivalent in any other industry. Where oil &amp; gas runs to API code body of knowledge and aerospace runs to NAS 410 / Nadcap, nuclear runs to a stack: ASME Section III for new construction, ASME Section XI for in-service inspection, ANSI/ASNT CP-189 for personnel certification (most US utilities default to CP-189 over the more flexible SNT-TC-1A precisely because the auditor expectation is sharper), 10 CFR 50 Appendix B for the quality assurance program in the US, and ASME NQA-1 as the implementing QA standard. Layered on top of all of that, ASME Section XI Mandatory Appendix VIII drives the Performance Demonstration Initiative — UT operators inspecting safety-class dissimilar-metal welds, reactor-pressure-vessel nozzles, or other sensitive geometries must close a practical demonstration on representative coupons before they are deployed. Our nuclear corporate program builds toward that documentation regime from day one. Every cohort starts with a written-practice review against the utility's own approved CP-189 written practice — we do not assume our defaults are the customer's defaults. Lesson plans are version-controlled and signed off by an Atlantis NDT ASNT Level III before the cohort starts. Every exam grade sheet, every vision record, every OJT log entry is captured in a QA-record-quality format that can be ingested directly into the utility's records management system. We coordinate PDI demonstration access through EPRI-recognised channels for the methods where that is required. The economics in nuclear sit higher per head than any other vertical we serve, which reflects the documentation overhead, the controlled-area training requirement, the PDI demonstration coordination, and the seniority of the instructor bench required to satisfy a utility QA reviewer. The benefit at the unit level is correspondingly large — a single missed indication on a steam-generator tube during an outage can drive a forced derate; a single failed PDI demonstration delays an outage critical path measured in days at a million dollars a day. Send unit count, outage cycle, and target methods — we respond inside two business days with a written training plan and indicative quote."};function l(){return e.jsx(t,{config:r})}export{l as default};
